ALTER TABLE "consent_texts" ADD COLUMN "covers_recording" boolean DEFAULT false NOT NULL;--> statement-breakpoint
-- Marks the exam consent texts that announce the continuous recording: the
-- built-in text (src/db/consent-text.ts, CONSENT_TR and CONSENT_EN), whether
-- the recording migration wrote it as the next version or a newer setup wrote
-- it as version 1. Every other text, the old built-in version 1 included,
-- stays false, so an invitation accepted under it is not recorded.
UPDATE "consent_texts" SET "covers_recording" = true
WHERE "solution" = 'LANGUAGE_EXAM'
  AND "body"->>'tr' = 'Bu sınav Almanca seviyenizi ölçmek içindir. Sınav boyunca kameranız ve mikrofonunuz açık kalır, ekranınızın tamamı paylaşılır ve sınav tam ekranda yapılır. Sınavın tamamı kaydedilir: kameranızın görüntüsü ve sesi, ekranınız paylaşılıyorsa ekranınız da. Bu kaydı yalnızca okulunuzun yetkili kullanıcıları izleyebilir. Pencere veya sekme değiştirme, kopyala-yapıştır denemeleri ve benzeri olaylar kaydedilir. Belirli aralıklarla ve şüpheli anlarda kameranızdan ve ekranınızdan kareler alınır; bu kareler yapay zekâ ile ikinci kez kontrol edilebilir. Yapay zekâ yalnızca görülen olguları not eder (kaç kişi var, bir cihaz görünüyor mu gibi), duygu veya kişilik çıkarımı yapmaz. Hiçbir işaret sizi otomatik olarak başarısız saymaz: hepsini öğretmeniniz inceler. Yazma ve konuşma cevaplarınız için yapay zekâ bir seviye önerir, nihai kararı öğretmeniniz verir. Kayıtlar okulun belirlediği süre boyunca saklanır ve sonra silinir. Verilerinizle ilgili taleplerinizi bu sayfadaki bağlantıdan iletebilirsiniz.'
  AND "body"->>'en' = 'This exam measures your German. During the exam your camera and microphone stay on, your whole screen is shared and the exam runs in full screen. The whole exam is recorded: the picture and sound from your camera, and your screen when it is shared. Only authorised staff of your school can watch this recording. Switching windows or tabs, copy and paste attempts and similar events are recorded. Frames from your camera and screen are taken at intervals and at suspicious moments; these frames may be checked a second time by AI. The AI only notes what can be seen (how many people, whether a device is visible), never emotions or personality. No flag fails you automatically: your teacher reviews all of them. For your writing and speaking answers the AI suggests a level; your teacher makes the final decision. Recordings are kept for the period your school sets and then deleted. You can send requests about your data from the link on this page.';
